UPDATE `broadcast_text` SET `Text` = 'This vendor is meant to help players who did the class hall quests in patch 7.0.3 and therefore cannot complete some quests right now. Below is the list of quests we can help such players with. If you have already completed these quests, you will not be able to turn them in again. Keep in mind that if everything is fine with the quests listed below, we strongly advise you NOT to use this vendor, as in your case it would most likely do more harm than good.' WHERE `ID` = '200008' AND `Text` REGEXP '[ÐÑÃ][^ ]';
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`) VALUES ('200008', 'frFR', 'Ce marchand aide les joueurs qui ont fait les quêtes de domaine de classe au patch 7.0.3 et qui, pour cette raison, ne peuvent pas terminer certaines quêtes pour le moment. Voici la liste des quêtes pour lesquelles nous pouvons les aider. Si vous avez déjà accompli ces quêtes, vous ne pourrez pas les rendre une seconde fois. Attention : si tout va bien pour vous avec les quêtes ci-dessous, nous vous déconseillons vivement d\'utiliser ce marchand, car il vous ferait sans doute plus de tort que de bien.') ON DUPLICATE KEY UPDATE `Text_lang` = IF(`Text_lang` IS NULL OR `Text_lang` = '' OR `Text_lang` REGEXP '[ÐÑÃ][^ ]' OR `Text_lang` REGEXP '[А-яЁё]', VALUES(`Text_lang`), `Text_lang`);
